import {generateOutline,rewriteBeat,generateProse,rewriteParagraph,paginateStory,rewriteStoryPage,repairPagination,summarizeStory} from './pipeline.js';
import {buildBeatPagePlan,splitPaginationToCount} from './pagination.js';
import {getTextModelInfo} from '../text-generation/models.js';
import {getTextGenerationSettings} from '../text-generation/settings-ui.js';
import {freezeReadingLevels} from '../reading-levels.js';
import {getActiveWorld} from '../image-generation/world.js';
import {availableCharacterVariants,validateWardrobeSelections} from '../wardrobe.js';
import {estimateBookCost} from '../image-generation/models.js';
import {checkStory} from './checker.js';
import {buildSeriesStorySelections} from './continuity.js';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const button=(label,action,data='',kind='outline')=>`<button type="button" class="btn btn-${kind} btn-small" data-story-action="${action}" ${data}>${label}</button>`;
const STAGE_NAMES={outline_draft:'줄거리 검토',outline_ok:'승인한 줄거리',prose_draft:'전문 검토',prose_ok:'승인한 전문',paged:'쪽 나누기 검토',illustrated:'그림 생성',final:'완성'};
const ENGINE_NAMES={anthropic:'Anthropic',openai:'OpenAI',google:'Google',local:'로컬 모델',demo:'데모'};
let api,session,configured=false,saveTimer;

function drafts(state){if(!state.storyDrafts||typeof state.storyDrafts!=='object')state.storyDrafts={};if(Array.isArray(state.storyDrafts))state.storyDrafts=Object.fromEntries(state.storyDrafts.filter(d=>d?.id&&d.stage!=='final').map(d=>[d.id,d]));return state.storyDrafts;}
function isHybrid(settings){return typeof settings.hybrid==='object'?settings.hybrid.enabled===true:!!(settings.hybrid||settings.hybridEnabled||settings.mode==='hybrid');}
function selectedModelName(settings){const id=engineId(settings);return getTextModelInfo(id,settings.providers?.[id]?.model).name;}
function engineId(settings){return isHybrid(settings)&&settings.hybrid?.finalEngine?settings.hybrid.finalEngine:(settings.engineId||settings.engine||settings.provider||'openai');}
function options(s,stage){if(s.draft.demo)return{engineId:'demo',signal:s.controller?.signal};const settings=s.draft.textSettings,local=isHybrid(settings)&&(stage==='outline'||stage==='proseDraft'),id=local?'local':engineId(settings);return{engineId:id,onCheckpoint:checkpoint=>{if(session!==s||api.getState()!==s.state||!api.isParent())return;s.draft.pagination=clone(checkpoint.pagination);s.draft.storyCheck=clone(checkpoint.checks);s.draft.paginationMeta={checks:clone(checkpoint.checks),repairAttempts:checkpoint.repairAttempts,incomplete:true};s.draft.stage='paged';s.mode='pages';saveDraft(s);},config:settings.providers?.[id]||settings.configs?.[id]||(local?settings.localConfig||settings.local:settings.config)||{},signal:s.controller?.signal,onProgress:progress=>{if(session!==s)return;const el=document.querySelector('#story-progress');if(el)el.textContent=typeof progress==='string'?progress:(progress.message||`검사와 수정 중 · ${progress.attempt??progress.completed??''}`);}};}
function ensure(s){if(session!==s||s.controller?.signal.aborted||api.getState()!==s.state||!api.isParent())throw new DOMException('이야기 작업을 중지했어요.','AbortError');}
function saveDraft(s){if(!s||api.getState()!==s.state||!api.isParent())return false;s.draft.updatedAt=new Date().toISOString();s.draft.reviewMode=s.mode;drafts(s.state)[s.draft.id]=s.draft;return api.save()!==false;}
function snapshot(s,kind){s.draft.snapshots||={};s.draft.snapshots[kind]||=[];const value=s.draft[kind];if(value)s.draft.snapshots[kind].push({at:new Date().toISOString(),data:clone(value)});if(s.draft.snapshots[kind].length>5)s.draft.snapshots[kind].shift();}
function stageStep(s){const mode=s.pendingMode||s.mode;return mode==='pages'?3:mode==='prose'?2:1;}
function header(s,title){const step=stageStep(s),previous=s.draft.input.previousStory;return `${api.modalHeader(title)}<ol class="story-steps">${['줄거리 카드','이야기 전문','쪽 나누기'].map((label,i)=>`<li class="${step===i+1?'current':step>i+1?'done':''}">${i+1} · ${label}</li>`).join('')}</ol>${s.draft.demo?'<p><span class="story-demo-label">데모</span><span class="story-note">API를 호출하지 않는 예시 이야기예요. 실제 엔진 생성과 구분해 보관합니다.</span></p>':''}<p class="story-note">글 엔진 ${esc(s.draft.demo?'무료 데모':selectedModelName(s.draft.textSettings))}${isHybrid(s.draft.textSettings)&&!s.draft.demo?' · 로컬 초안 + 선택 API 최종 전문':''} · 그림 엔진 ${esc(s.draft.worldSnapshot.imageEngine)} · ${esc(s.draft.input.specs.ko.id)} / ${esc(s.draft.input.specs.en.id)} · ${s.draft.input.pageCount}쪽</p>${!s.draft.demo&&!s.busy?`<div class="story-inline-actions">${button('설정의 글 엔진 적용','use-current-text-settings')}<small class="story-note">초안을 지우지 않고 현재 World의 엔진·모델로 다음 요청부터 바꿉니다.</small></div>`:''}${previous?`<details class="story-card"><summary>이전 편을 읽고 이어 쓰기 · ${esc(previous.title)}</summary><p class="story-note">이전 편의 사건·마지막 장면·등장인물과 아래 전문을 글 엔진에 함께 보내 다음 편을 만들어요. 다음 편 그림은 이전 책에서 확정한 인물·장소·화풍과 이미지 엔진을 이어 사용합니다. 글 엔진은 별도로 선택합니다.</p><strong>한글 전문</strong><p style="white-space:pre-wrap;line-height:1.7">${esc(previous.prose.ko)}</p><strong>English</strong><p style="white-space:pre-wrap;line-height:1.7">${esc(previous.prose.en)}</p></details>`:''}`;}
function show(s,content){if(session!==s)return;api.showModal(content,'wide story-workspace');}
function error(s,message){if(session!==s)return;const el=document.querySelector('#story-error');if(el)el.textContent=message;else api.toast(message);}
function note(){return '<p class="story-note">입력한 내용과 단계별 결과는 이 브라우저의 초안으로 저장돼요. 닫았다가 다시 이어서 만들 수 있습니다. 각 다시 쓰기와 다음 단계 생성에는 선택 엔진의 요청 요금이 적용될 수 있어요.</p><p id="story-error" class="story-error" aria-live="polite"></p>';}
function inputFromWizard(state,wizard){
  const choices=validateWardrobeSelections(state,wizard),previous=state.books.find(book=>book.id===wizard.previousBookId),world=clone(getActiveWorld(state));
  const inherited=buildSeriesStorySelections(state,wizard,previous),characters=inherited.characters;
  if(!characters.length)throw new Error('이야기의 주인공을 먼저 골라 주세요.');
  const readingLevels=freezeReadingLevels({...wizard,koVocabulary:state.settings.koVocabularies?.[Number(String(wizard.koreanLevel||'K1').slice(1))]?.words||[]},state.settings);
  const variants=(wizard.characterIds||[]).map(id=>state.characters.find(c=>c.id===id)).filter(Boolean).flatMap(c=>availableCharacterVariants(state,c).map(v=>({id:v.id,characterId:c.id,name:v.name,description:v.description})));
  if(previous?.generationSnapshot){world.imageEngine=previous.generationSnapshot.imageEngine||previous.imageEngine||world.imageEngine;world.stylePresetId=previous.generationSnapshot.stylePresetId||previous.stylePresetId||world.stylePresetId;}
  return{input:{characters,backgrounds:inherited.backgrounds,worldNotes:inherited.worldNotes,topic:String(wizard.topic||'').trim(),pageCount:Number(wizard.pageCount||12),endingType:wizard.ending==='open'?'open':'home_sleep',moral:wizard.value==='none'?'':wizard.value||'',previousSummary:previous?.summaryForNext||previous?.outline?.logline||'',previousStory:inherited.previousStory,specs:readingLevels.specs,variants,variantByCharacter:choices.characterVariants,variantPageRanges:choices.variantPageRanges},readingLevels,world};
}

export function configureStoryUI(context){api=context;if(configured)return;configured=true;document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);}
export function cleanupStoryWorkflow(){clearTimeout(saveTimer);if(session?.elapsedTimer)clearInterval(session.elapsedTimer);if(session){captureEdits(session);session.controller?.abort();saveDraft(session);}session=null;}
export function renderStoryDrafts(state){const list=Object.values(state.storyDrafts||{}).filter(d=>d?.id&&d.stage!=='final').sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')));if(!list.length)return '';return `<section class="panel"><h3>이어 만들 이야기</h3><p class="small-label">승인하기 전 줄거리와 전문도 기기에 저장돼 있어요.</p><div class="story-drafts">${list.map(d=>`<article class="story-draft-card"><strong>${d.demo?'<span class="story-demo-label">데모</span>':''}${esc(d.selectedTitle||d.outline?.titleCandidates?.[0]||d.input?.topic||'새 이야기')}</strong><p>${esc(STAGE_NAMES[d.stage]||'생성 준비')} · 목표 ${d.input?.pageCount||12}쪽${d.pagination?.pages?` · 현재 ${d.pagination.pages.length}쪽`:''}</p><div class="story-inline-actions">${button('이어서 만들기','resume',`data-id="${esc(d.id)}"`)}${button('초안 삭제','delete-draft',`data-id="${esc(d.id)}"`)}</div></article>`).join('')}</div></section>`;}
export function startStoryWorkflow(wizard){if(!api.isParent())return api.protectedAction(()=>startStoryWorkflow(wizard));cleanupStoryWorkflow();const state=api.getState();try{const prepared=inputFromWizard(state,wizard),textSettings=clone(getTextGenerationSettings(state));session={state,draft:{id:`story-${crypto.randomUUID()}`,stage:'outline_draft',wizard:clone(wizard),input:prepared.input,readingLevels:prepared.readingLevels,worldId:prepared.world.id,worldSnapshot:prepared.world,textSettings,usage:{calls:[]},createdAt:new Date().toISOString()},mode:'launch',busy:false,language:'ko'};saveDraft(session);renderLaunch(session);}catch(err){api.toast(err.message);}}
export function resumeStoryDraft(id){if(!api.isParent())return api.protectedAction(()=>resumeStoryDraft(id));cleanupStoryWorkflow();const state=api.getState(),draft=drafts(state)[id];if(!draft)return api.toast('저장한 이야기 초안을 찾지 못했어요.');session={state,draft,mode:draft.reviewMode==='outline'&&draft.outline?'outline':draft.reviewMode==='prose'&&draft.prose?'prose':draft.pagination?'pages':draft.prose?'prose':draft.outline?'outline':'launch',busy:false,language:'ko'};renderSession(session);}
/** Keep edits made in the existing picture editor when it reopens this workflow. */
export function syncStoryDraft(book,state){const d=drafts(state)[book.storyDraftId];if(!d)return false;if(book.outline)d.outline=clone(book.outline);if(book.prose)d.prose=clone(book.prose);if(d.pagination&&book.pages?.length)d.pagination.pages=book.pages.map((page,index)=>({pageNo:index+1,beatIndex:page.beatIndex??d.pagination.pages[index]?.beatIndex??1,textKo:page.ko??page.textKo??'',textEn:page.en??page.textEn??'',scene:clone({...d.pagination.pages[index]?.scene,...page.scene}),variantByCharacter:clone(page.variantByCharacter||d.pagination.pages[index]?.variantByCharacter||{}),isRefrainPage:!!page.isRefrainPage}));d.checksDirty=true;d.updatedAt=new Date().toISOString();return true;}

function costValue(value){if(Number.isFinite(value))return `$${value.toFixed(4)}`;if(value&&Number.isFinite(value.estimatedUsd??value.costUsdEstimated??value.totalUsd??value.costUsd??value.usd))return `$${Number(value.estimatedUsd??value.costUsdEstimated??value.totalUsd??value.costUsd??value.usd).toFixed(4)}`;return '요청 길이·모델에 따라 결정';}
function renderLaunch(s){const estimate=api.estimateStoryTextCost?.({pageCount:s.draft.input.pageCount,engineId:engineId(s.draft.textSettings),settings:s.draft.textSettings,previousTextLength:(s.draft.input.previousStory?.prose?.ko?.length||0)+(s.draft.input.previousStory?.prose?.en?.length||0)});let imageEstimate;try{imageEstimate=estimateBookCost({engine:s.draft.worldSnapshot.imageEngine,quality:'final',pageCount:s.draft.input.pageCount,includeCover:true,config:s.draft.worldSnapshot.providerConfig?.[s.draft.worldSnapshot.imageEngine]||{}});}catch{}show(s,`${header(s,'사건이 있는 이야기를 만들어요')}<p class="modal-intro">줄거리의 사건과 반전을 먼저 정하고, 한글·영어 전문을 쓴 뒤 쪽으로 나눠요. 부모가 세 단계마다 고치고 승인합니다.</p><div class="story-cost"><strong>글 + 그림 예상 비용</strong>글: ${esc(costValue(estimate))}<br>최종 그림 ${s.draft.input.pageCount+1}장: ${esc(costValue(imageEstimate))}<br><small>추정 비용이며 다시 쓰기·자동 수정·그림 초안은 추가 요청입니다. 실제 청구액은 공급자 사용량에서 확인하세요.</small></div><p class="story-note">주제: ${esc(s.draft.input.topic)}<br>줄거리 생성은 글 엔진에 등장인물 설정·세계관·주제·읽기 수준을 보냅니다. 사진과 이미지 API 키는 글 요청에 포함하지 않습니다.</p>${note()}<div class="modal-actions">${button('나중에 이어 만들기','close')}${button('데모로 세 단계 살펴보기 · 무료','start-demo')}${button('줄거리 생성 · API 요청','start-api','','primary')}</div>`);}
function renderSession(s){if(!s||session!==s)return;if(s.mode==='launch')renderLaunch(s);else if(s.mode==='outline')renderOutline(s);else if(s.mode==='prose')renderProse(s);else renderPages(s);}

function renderOutline(s){const o=s.draft.outline,plan=buildBeatPagePlan(o,s.draft.input.pageCount);show(s,`${header(s,'줄거리 카드')}<p class="modal-intro">줄거리 비트 ${o.beats.length}개를 나중에 ${s.draft.input.pageCount}쪽으로 나눕니다. 비트 번호는 책의 쪽 번호가 아닙니다. 원하는 것 → 시도 → 반전 → 해결을 확인해 주세요.</p><div class="story-card"><label class="story-label">제목 후보 · 하나를 고르거나 직접 고쳐 주세요</label>${o.titleCandidates.map((title,i)=>`<label class="story-title-pick"><input type="radio" name="story-title" value="${i}" ${s.draft.titleIndex===i?'checked':''}><input type="text" maxlength="150" data-outline-title="${i}" value="${esc(title)}" aria-label="제목 후보 ${i+1}"></label>`).join('')}<div class="field"><label>한 줄 요약</label><input data-outline-field="logline" value="${esc(o.logline)}" maxlength="1000"></div><div class="story-review-grid">${[['want','주인공이 원하는 것'],['problem','막아서는 문제'],['twist','아이를 놀라게 할 반전']].map(([key,label])=>`<div class="field ${key==='twist'?'field-wide':''}"><label>${label}</label><textarea data-outline-field="${key}" maxlength="2000">${esc(o[key])}</textarea></div>`).join('')}</div></div>${o.beats.map((beat,i)=>`<article class="story-card"><div class="story-card-head"><strong>비트 ${i+1} · ${esc({setup:'시작',want:'바람',attempt:'시도',turn:'반전',resolution:'해결',close:'마무리'}[beat.type]||beat.type)} · ${plan.filter(page=>page.beatIndex===beat.index).map(page=>page.pageNo).join('·')}쪽 예정</strong>${button('이 비트만 다시','rewrite-beat',`data-index="${i}"`)}</div><div class="field"><label class="story-label">구체적으로 무슨 일이 달라지나요?</label><textarea data-beat-field="summary" data-index="${i}" maxlength="5000">${esc(beat.summary)}</textarea></div><div class="story-review-grid"><div class="field"><label class="story-label">장소</label><input data-beat-field="settingKey" data-index="${i}" value="${esc(beat.settingKey)}"></div><div class="field"><label class="story-label">감정</label><input data-emotion-index="${i}" value="${esc(o.emotionArc?.[i]||'')}"></div></div></article>`).join('')}<div class="story-card"><div class="story-review-grid"><div class="field"><label>후렴 · 없으면 비워 두세요</label><input id="story-refrain" value="${esc(o.refrain?.text||'')}" maxlength="300"></div><div class="field"><label>후렴을 쓸 비트 번호 · 최대 3곳</label><input id="story-refrain-beats" value="${esc(o.refrain?.usedAtBeats?.join(', ')||'')}" placeholder="3, 5, 7"></div><div class="field"><label>새 한글 단어</label><input data-outline-words="newWordsKo" value="${esc(o.newWordsKo?.join(', ')||'')}"></div><div class="field"><label>새 영어 단어</label><input data-outline-words="newWordsEn" value="${esc(o.newWordsEn?.join(', ')||'')}"></div></div></div>${note()}<div class="modal-actions">${button('저장하고 닫기','close')}${button('줄거리 전체 다시','regenerate-outline')}${button('줄거리 승인 · 전문 생성','approve-outline','','primary')}</div>`);}
function renderProse(s){const p=s.draft.prose,language=s.language||'ko',paragraphs=String(p[language]||'').split(/\n\s*\n/).filter(Boolean),needsFinal=isHybrid(s.draft.textSettings)&&!s.draft.demo&&!s.draft.hybridFinal;show(s,`${header(s,'이야기 전문')}<p class="modal-intro">비트마다 상황이 바뀌는지, 반전이 실제 글에 있는지 읽어 주세요. 영어는 같은 사건으로 새로 쓴 글입니다.</p>${needsFinal?'<div class="notice">로컬 모델의 전문 초안입니다. 선택한 API로 최종 전문을 다듬은 뒤 부모가 승인합니다.</div>':''}<div class="story-prose-tabs">${button('한글','prose-tab','data-language="ko"',language==='ko'?'green':'outline')}${button('English','prose-tab','data-language="en"',language==='en'?'green':'outline')}</div><label class="story-label">${language==='ko'?'한글':'영어'} 전문 · 문단 사이에 빈 줄을 넣어 주세요</label><textarea class="story-prose" id="story-prose" data-language="${language}" maxlength="50000">${esc(p[language])}</textarea><details class="story-card"><summary>이 문단만 다시 쓰기</summary>${paragraphs.map((paragraph,i)=>`<div class="story-paragraph"><p>${esc(paragraph)}</p>${button(`${i+1}번째 문단만 다시`,'rewrite-paragraph',`data-index="${i}" data-language="${language}"`)}</div>`).join('')}</details>${note()}<div class="modal-actions">${button('줄거리로 돌아가기','back-outline')}${button('저장하고 닫기','close')}${button('전문 다시 쓰기 · 비트 유지','regenerate-prose')}${needsFinal?button('선택 API로 최종 전문 다듬기','hybrid-final','','primary'):button('전문 승인 · 쪽 나누기','approve-prose','','primary')}</div>`);}

function checkView(s){const c=s.draft.storyCheck||s.draft.paginationMeta?.checks;if(!c)return '<p class="story-note">쪽 수정 뒤 검사 결과를 다시 확인해 주세요.</p>';const entries=Array.isArray(c.items)?c.items:Array.isArray(c.checks)?c.checks:Array.isArray(c.results)?c.results:Object.entries(c.checks||{}).map(([id,value])=>({id,...(typeof value==='object'?value:{passed:value})}));return `<div class="story-card story-check-details"><strong>이야기 자동 검사</strong><p>${c.passed===true?'검사 기준을 통과했어요.':c.passed===false?'수정이 필요한 항목이 있어요. 배지를 확인해 주세요.':'최신 쪽에 대한 검사 결과입니다.'}</p>${entries.map(item=>`<span class="story-check-badge ${item.passed===false||item.ok===false?'fail':''}">${esc(item.label||item.name||item.id||item.type)} ${item.passed===false||item.ok===false?'확인 필요':'확인'}</span>`).join('')}${Array.isArray(c.violations)&&c.violations.length?`<ul>${c.violations.map(item=>`<li>${item.pageNo?`${item.pageNo}쪽 · `:''}${esc(item.message||item.reason||item.type||item.code)}</li>`).join('')}</ul>`:''}${s.draft.checksDirty?'<p class="story-note">글이나 장면을 수정했어요. 그림 생성 전에 최신 내용으로 다시 검사합니다.</p>':''}</div>`;}
function renderPages(s){const p=s.draft.pagination,cast=s.draft.input.characters,target=s.draft.input.pageCount,mismatch=p.pages.length!==target;show(s,`${header(s,'쪽 나누기')}<p class="modal-intro">현재 ${p.pages.length}쪽 / 목표 ${target}쪽 · ${s.draft.outline.beats.length}개 비트를 여러 쪽에 나눠 담습니다.</p>${mismatch?`<div class="notice story-count-warning" role="status"><strong>${p.pages.length}쪽으로 생성되어 ${target}쪽 복구가 필요해요.</strong><p>줄거리와 전문은 저장되어 있습니다. AI로 다시 나누거나, 기존 쪽 글을 그대로 나눌 수 있어요.</p><div class="story-inline-actions">${button(`AI로 ${target}쪽 다시 나누기 · API 요청`,'repaginate','', 'primary')}${p.pages.length<target?button(`API 없이 기존 글 ${target}쪽으로 나누기`,'fit-page-count'):''}</div></div>`:''}${s.draft.paginationMeta?.manualRedistribution?'<div class="notice">기존 글을 보존해 쪽만 나눈 초안입니다. 짧아진 문장과 같은 장면의 구도를 검토하고, 필요한 쪽만 AI로 다듬어 주세요.</div>':''}<div class="story-inline-actions"><label class="field">쪽 수 <select id="story-page-count">${[8,12,16,24].map(n=>`<option value="${n}" ${s.draft.input.pageCount===n?'selected':''}>${n}쪽</option>`).join('')}</select></label>${button('전문 유지 · 쪽만 다시 나누기','repaginate')}${button('검사 후 실패 쪽만 수정 · 최대 2회','repair-pages')}</div>${checkView(s)}<div class="story-card"><div class="field"><label>표지 제목</label><input data-cover-field="title" value="${esc(p.cover.title)}" maxlength="150"></div><div class="field"><label>표지 장면 · 영어</label><textarea data-cover-field="sceneAction" maxlength="1000">${esc(p.cover.sceneAction)}</textarea></div></div>${p.pages.map((page,i)=>`<article class="story-card" data-story-page="${i}"><div class="story-card-head"><strong>${i+1}쪽 · ${page.beatIndex}번 비트</strong><div class="story-inline-actions">${button('이 쪽만 다시','rewrite-page',`data-index="${i}"`)}${button('쪽 나누기','split-page',`data-index="${i}"`)}${i<p.pages.length-1?button('다음 쪽과 합치기','merge-page',`data-index="${i}"`):''}</div></div><div class="story-review-grid"><div class="field"><label>한글</label><textarea data-page-field="textKo" data-index="${i}" maxlength="15000">${esc(page.textKo)}</textarea></div><div class="field"><label>English</label><textarea data-page-field="textEn" data-index="${i}" maxlength="15000">${esc(page.textEn)}</textarea></div></div><div class="story-page-scene"><div class="field"><label>그릴 한 장면 · 영어 동작 설명</label><textarea data-scene-field="action" data-index="${i}" maxlength="2500">${esc(page.scene.action)}</textarea></div><div class="story-review-grid"><div class="field"><label>배경 ID 또는 장소 설명</label><input data-scene-field="where" data-index="${i}" value="${esc(page.scene.where)}"></div><div class="field"><label>감정 · 영어 한 단어</label><input data-scene-field="emotion" data-index="${i}" value="${esc(page.scene.emotion)}"></div><div class="field"><label>시간</label><select data-scene-field="timeOfDay" data-index="${i}">${['morning','day','evening','night'].map(time=>`<option value="${time}" ${page.scene.timeOfDay===time?'selected':''}>${({morning:'아침',day:'낮',evening:'저녁',night:'밤'})[time]}</option>`).join('')}</select></div><div class="field"><label>소품 · 영어, 쉼표로 구분</label><input data-scene-field="props" data-index="${i}" value="${esc(page.scene.props?.join(', ')||'')}"></div></div><div class="story-page-variants">${cast.map(character=>`<label class="story-label">${esc(character.name)}의 모습<select data-page-variant="${esc(character.id)}" data-index="${i}"><option value="">기본 시트</option>${s.draft.input.variants.filter(v=>v.characterId===character.id).map(v=>`<option value="${esc(v.id)}" ${page.variantByCharacter?.[character.id]===v.id?'selected':''}>${esc(v.name||v.id)}</option>`).join('')}</select></label>`).join('')}</div></div></article>`).join('')}${note()}<label class="story-note"><input type="checkbox" id="story-accept-failures"> 검사 경고가 남아 있으면 내용을 확인한 뒤 그대로 그림 단계로 진행합니다.</label><div class="modal-actions">${button('전문으로 돌아가기','back-prose')}${button('저장하고 닫기','close')}${button('쪽 승인 · 그림 단계로','approve-pages',mismatch?'disabled aria-describedby="story-page-count"':'','primary')}</div>`);}

function captureEdits(s){if(!s||session!==s||s.busy)return;const d=s.draft,beforeOutline=JSON.stringify(d.outline),beforeProse=JSON.stringify(d.prose);if(s.mode==='outline'&&d.outline){document.querySelectorAll('[data-outline-title]').forEach(el=>d.outline.titleCandidates[Number(el.dataset.outlineTitle)]=el.value);const picked=document.querySelector('input[name="story-title"]:checked');d.titleIndex=Number(picked?.value??d.titleIndex??0);d.selectedTitle=d.outline.titleCandidates[d.titleIndex];document.querySelectorAll('[data-outline-field]').forEach(el=>d.outline[el.dataset.outlineField]=el.value);document.querySelectorAll('[data-beat-field]').forEach(el=>d.outline.beats[Number(el.dataset.index)][el.dataset.beatField]=el.value);document.querySelectorAll('[data-emotion-index]').forEach(el=>(d.outline.emotionArc||=[])[Number(el.dataset.emotionIndex)]=el.value);document.querySelectorAll('[data-outline-words]').forEach(el=>d.outline[el.dataset.outlineWords]=el.value.split(',').map(w=>w.trim()).filter(Boolean));const ref=document.querySelector('#story-refrain');if(ref)d.outline.refrain=ref.value.trim()?{text:ref.value.trim(),usedAtBeats:(document.querySelector('#story-refrain-beats')?.value||'').split(',').map(Number).filter(n=>Number.isInteger(n)&&n>=1&&n<=d.outline.beats.length)}:undefined;}
 if(s.mode==='outline'&&d.outline&&beforeOutline!==JSON.stringify(d.outline)){snapshot(s,'prose');snapshot(s,'pagination');d.prose=null;d.pagination=null;d.hybridFinal=false;d.stage='outline_draft';}
 if(s.mode==='prose'&&d.prose){const field=document.querySelector('#story-prose');if(field)d.prose[field.dataset.language]=field.value;}
 if(s.mode==='prose'&&d.prose&&beforeProse!==JSON.stringify(d.prose)){snapshot(s,'pagination');d.pagination=null;d.stage='prose_draft';}
 if(s.mode==='pages'&&d.pagination){document.querySelectorAll('[data-cover-field]').forEach(el=>d.pagination.cover[el.dataset.coverField]=el.value);document.querySelectorAll('[data-page-field]').forEach(el=>d.pagination.pages[Number(el.dataset.index)][el.dataset.pageField]=el.value);document.querySelectorAll('[data-scene-field]').forEach(el=>d.pagination.pages[Number(el.dataset.index)].scene[el.dataset.sceneField]=el.dataset.sceneField==='props'?el.value.split(',').map(w=>w.trim()).filter(Boolean):el.value);document.querySelectorAll('[data-page-variant]').forEach(el=>(d.pagination.pages[Number(el.dataset.index)].variantByCharacter||={})[el.dataset.pageVariant]=el.value||null);}
}
function addUsage(s,result){s.draft.usage.calls.push({at:new Date().toISOString(),...clone(result.usage||{}),...clone(result.meta||{})});}
async function run(s,label,fn,done){if(s.busy)return;captureEdits(s);saveDraft(s);s.busy=true;s.controller=new AbortController();show(s,`${header(s,label)}<div class="story-progress" id="story-progress">${esc(label)} · 완료된 결과는 초안에 저장돼 있어요.</div><p class="story-note" id="story-elapsed" aria-live="off">경과 0초 · 중지해도 저장된 결과를 이어서 만들 수 있어요.</p><p id="story-error" class="story-error"></p><div class="modal-actions">${button('작업 중지 · 초안 보관','stop')}</div>`);const started=Date.now();s.elapsedTimer=setInterval(()=>{const el=document.querySelector('#story-elapsed');if(session===s&&el)el.textContent=`경과 ${Math.floor((Date.now()-started)/1000)}초 · 추론 모델은 몇 분 걸릴 수 있어요. 중지하면 저장한 결과가 남습니다.`;},1000);try{const result=await fn();ensure(s);addUsage(s,result);done(result);clearInterval(s.elapsedTimer);s.elapsedTimer=null;s.pendingMode=null;s.busy=false;s.controller=null;if(!saveDraft(s))throw new Error('이야기 초안을 저장하지 못했어요. 백업 후 저장 공간을 확인해 주세요.');renderSession(s);}catch(err){if(session!==s)return;clearInterval(s.elapsedTimer);s.elapsedTimer=null;s.pendingMode=null;s.busy=false;s.controller=null;renderSession(s);error(s,err.name==='AbortError'?'이번 요청을 중지했어요. 이전 단계와 부모 수정은 초안에 남아 있습니다.':err.message||'이야기 생성에 실패했어요.');}}
function acceptOutline(s){captureEdits(s);const o=s.draft.outline;if(!o.titleCandidates[s.draft.titleIndex||0]?.trim())throw new Error('제목을 적어 주세요.');if(o.beats.some(b=>!b.summary?.trim()))throw new Error('비트마다 사건을 적어 주세요.');if(o.refrain?.usedAtBeats?.length>3)throw new Error('후렴은 최대 3개 비트에서 사용해 주세요.');s.draft.selectedTitle=o.titleCandidates[s.draft.titleIndex||0];s.draft.input.title=s.draft.selectedTitle;s.draft.stage='outline_ok';snapshot(s,'outline');}
function acceptProse(s){captureEdits(s);if(!s.draft.prose.ko?.trim()||!s.draft.prose.en?.trim())throw new Error('한글과 영어 전문을 모두 확인해 주세요.');if(isHybrid(s.draft.textSettings)&&!s.draft.demo&&!s.draft.hybridFinal)throw new Error('선택한 API로 최종 전문을 다듬은 뒤 승인해 주세요.');s.draft.stage='prose_ok';snapshot(s,'prose');}
function markPagesDirty(s){s.draft.checksDirty=true;s.draft.stage='paged';}
function renumber(s){s.draft.pagination.pages.forEach((page,i)=>page.pageNo=i+1);markPagesDirty(s);saveDraft(s);renderPages(s);}
function divide(text){const sentences=String(text||'').match(/[^.!?。！？]+[.!?。！？]+[”’"']?|[^.!?。！？]+$/g)||[];if(sentences.length>=2){const middle=Math.ceil(sentences.length/2);return[sentences.slice(0,middle).join('').trim(),sentences.slice(middle).join('').trim()];}const words=String(text||'').split(/\s+/).filter(Boolean);if(words.length<2)return[text,''];const mid=Math.ceil(words.length/2);return[words.slice(0,mid).join(' '),words.slice(mid).join(' ')];}
async function approvePages(s){captureEdits(s);const checked=checkStory(s.draft.outline,s.draft.pagination,{specs:s.draft.input.specs,allowedNames:s.draft.input.characters.flatMap(c=>[c.name,c.nameEn]).filter(Boolean)});ensure(s);if(checked)s.draft.storyCheck=checked;s.draft.checksDirty=false;if(s.draft.pagination.pages.length!==s.draft.input.pageCount)throw new Error(`현재 ${s.draft.pagination.pages.length}쪽 / 목표 ${s.draft.input.pageCount}쪽입니다. 위의 복구 버튼으로 쪽 수를 맞춰 주세요.`);if(s.draft.storyCheck?.passed===false&&!document.querySelector('#story-accept-failures')?.checked){renderPages(s);throw new Error('검사 경고를 먼저 확인하거나 글을 수정해 주세요. 확인 후 진행하려면 아래 체크란을 선택해 주세요.');}s.draft.stage='paged';snapshot(s,'pagination');saveDraft(s);const payload={id:s.draft.id,wizard:clone(s.draft.wizard),input:clone(s.draft.input),outline:clone(s.draft.outline),prose:clone(s.draft.prose),pagination:clone(s.draft.pagination),stage:'paged',textEngineId:s.draft.demo?'demo':engineId(s.draft.textSettings),textModelId:s.draft.demo?'demo':getTextModelInfo(engineId(s.draft.textSettings),s.draft.textSettings.providers?.[engineId(s.draft.textSettings)]?.model).id,textSettings:clone(s.draft.textSettings),summaryForNext:summarizeStory(s.draft.outline,{...s.draft.input,prose:s.draft.prose,pagination:s.draft.pagination}),readingLevels:clone(s.draft.readingLevels),usage:clone(s.draft.usage),storyCheck:clone(s.draft.storyCheck||s.draft.paginationMeta?.checks||{}),demo:!!s.draft.demo,worldId:s.draft.worldId,worldSnapshot:clone(s.draft.worldSnapshot)};s.busy=true;try{await api.onReady(payload);if(session===s)session=null;}catch(err){s.busy=false;throw err;}}

async function handleClick(event){const el=event.target.closest('[data-story-action]');if(!el)return;event.preventDefault();const action=el.dataset.storyAction;if(action==='resume'){api.protectedAction(()=>resumeStoryDraft(el.dataset.id));return;}if(action==='delete-draft'){api.protectedAction(()=>{const state=api.getState();delete drafts(state)[el.dataset.id];if(api.save()!==false){api.render();api.toast('이야기 초안을 삭제했어요.');}});return;}const s=session;if(!s||!api.isParent())return;if(action==='close'){cleanupStoryWorkflow();api.closeModal();api.render();return;}if(action==='stop'){s.controller?.abort();return;}if(s.busy)return;s.pendingMode=['approve-outline','regenerate-prose','hybrid-final','rewrite-paragraph'].includes(action)?'prose':['approve-prose','repaginate','repair-pages','rewrite-page'].includes(action)?'pages':null;try{captureEdits(s);saveDraft(s);const d=s.draft;if(action==='use-current-text-settings'){d.textSettings=clone(getTextGenerationSettings(s.state));saveDraft(s);renderSession(s);api.toast('저장된 글과 줄거리는 유지하고 현재 World의 글 엔진을 적용했어요.');return;}if(action==='fit-page-count'){snapshot(s,'pagination');const fitted=splitPaginationToCount(d.pagination,d.input.pageCount,{outline:d.outline});d.pagination=fitted;d.storyCheck=checkStory(d.outline,fitted,{specs:d.input.specs,allowedNames:d.input.characters.flatMap(c=>[c.name,c.nameEn]).filter(Boolean)});d.paginationMeta={checks:d.storyCheck,manualRedistribution:true};d.checksDirty=false;renumber(s);return;}if(action==='start-api'||action==='start-demo'){d.demo=action==='start-demo';return run(s,'줄거리를 만들고 있어요',()=>generateOutline(d.input,options(s,'outline')),r=>{d.outline=r.data;d.titleIndex=0;d.selectedTitle=d.outline.titleCandidates[0];d.stage='outline_draft';s.mode='outline';});}if(action==='regenerate-outline')return run(s,'줄거리 전체를 다시 만들고 있어요',()=>generateOutline(d.input,options(s,'outline')),r=>{snapshot(s,'outline');d.outline=r.data;d.prose=null;d.pagination=null;d.hybridFinal=false;d.stage='outline_draft';s.mode='outline';});if(action==='rewrite-beat')return run(s,`${Number(el.dataset.index)+1}번 비트만 다시 만들고 있어요`,()=>rewriteBeat(d.outline,Number(el.dataset.index),d.input,options(s,'outline')),r=>{snapshot(s,'outline');d.outline=r.data;d.stage='outline_draft';});if(action==='approve-outline'){acceptOutline(s);return run(s,'같은 사건으로 한글·영어 전문을 쓰고 있어요',()=>generateProse(d.outline,d.input,options(s,isHybrid(d.textSettings)?'proseDraft':'prose')),r=>{d.prose=r.data;d.pagination=null;d.hybridFinal=!isHybrid(d.textSettings)||d.demo;d.stage='prose_draft';s.mode='prose';});}if(action==='prose-tab'){s.language=el.dataset.language;renderProse(s);return;}if(action==='back-outline'){s.mode='outline';renderOutline(s);return;}if(action==='back-prose'){s.mode='prose';renderProse(s);return;}if(action==='regenerate-prose'||action==='hybrid-final')return run(s,action==='hybrid-final'?'선택 API로 최종 전문을 다듬고 있어요':'비트를 유지하고 전문을 다시 쓰고 있어요',()=>generateProse(d.outline,{...d.input,...(action==='hybrid-final'?{draftProse:clone(d.prose)}:{})},options(s,action==='hybrid-final'?'prose':'proseDraft')),r=>{snapshot(s,'prose');d.prose=r.data;d.pagination=null;d.hybridFinal=action==='hybrid-final'||!isHybrid(d.textSettings)||d.demo;d.stage='prose_draft';s.mode='prose';});if(action==='rewrite-paragraph')return run(s,'선택한 문단만 다시 쓰고 있어요',()=>rewriteParagraph(d.prose,el.dataset.language,Number(el.dataset.index),d.outline,d.input,options(s,d.hybridFinal?'prose':'proseDraft')),r=>{snapshot(s,'prose');d.prose=r.data;d.stage='prose_draft';});if(action==='approve-prose'){acceptProse(s);return run(s,'승인한 전문을 쪽으로 나누고 검사하고 있어요',()=>paginateStory(d.outline,d.prose,d.input,options(s,'pagination')),r=>{d.pagination=r.data;d.paginationMeta=r.meta;d.storyCheck=r.meta?.checks;d.checksDirty=false;d.stage='paged';s.mode='pages';});}if(action==='repaginate'){d.input.pageCount=Number(document.querySelector('#story-page-count').value);d.wizard.pageCount=d.input.pageCount;return run(s,'전문은 유지하고 쪽만 다시 나누고 있어요',()=>paginateStory(d.outline,d.prose,d.input,options(s,'pagination')),r=>{snapshot(s,'pagination');d.pagination=r.data;d.paginationMeta=r.meta;d.storyCheck=r.meta?.checks;d.checksDirty=false;});}if(action==='repair-pages')return run(s,'실패한 쪽을 최대 두 번 수정하고 있어요',()=>repairPagination(d.outline,d.prose,d.pagination,d.input,options(s,'pagination')),r=>{snapshot(s,'pagination');d.pagination=r.data;d.paginationMeta=r.meta;d.storyCheck=r.meta?.checks;d.checksDirty=false;});if(action==='rewrite-page')return run(s,`${Number(el.dataset.index)+1}쪽만 다시 쓰고 있어요`,()=>rewriteStoryPage(d.pagination,Number(el.dataset.index)+1,d.outline,d.prose,d.input,options(s,'pagination')),r=>{snapshot(s,'pagination');d.pagination=r.data;d.paginationMeta=r.meta;d.storyCheck=r.meta?.checks;d.checksDirty=!r.meta?.checks;});if(action==='split-page'){const i=Number(el.dataset.index),page=d.pagination.pages[i],ko=divide(page.textKo),en=divide(page.textEn);if(!ko[1]&&!en[1])throw new Error('한 문장만 있는 쪽은 직접 글을 나누거나 쪽만 다시 나누기를 사용해 주세요.');snapshot(s,'pagination');page.textKo=ko[0];page.textEn=en[0];d.pagination.pages.splice(i+1,0,{...clone(page),textKo:ko[1],textEn:en[1]});renumber(s);return;}if(action==='merge-page'){const i=Number(el.dataset.index),a=d.pagination.pages[i],b=d.pagination.pages[i+1];if(!b)return;if(a.beatIndex!==b.beatIndex||a.scene.where!==b.scene.where||a.scene.timeOfDay!==b.scene.timeOfDay)throw new Error('같은 비트·장소·시간의 쪽을 합칠 수 있어요. 장면이 다르면 쪽만 다시 나누기를 사용해 주세요.');snapshot(s,'pagination');a.textKo=[a.textKo,b.textKo].filter(Boolean).join(' ');a.textEn=[a.textEn,b.textEn].filter(Boolean).join(' ');a.isRefrainPage=!!(a.isRefrainPage||b.isRefrainPage);d.pagination.pages.splice(i+1,1);renumber(s);return;}if(action==='approve-pages')await approvePages(s);}catch(err){if(err.name!=='AbortError')error(s,err.message);}}
function handleInput(event){if(!session||session.busy||!api.isParent()||!event.target.closest('.story-workspace'))return;if(session.mode==='pages')markPagesDirty(session);clearTimeout(saveTimer);saveTimer=setTimeout(()=>{if(session){captureEdits(session);saveDraft(session);}},250);}
function handleChange(event){if(!session||session.busy||!api.isParent()||!event.target.closest('.story-workspace'))return;captureEdits(session);saveDraft(session);}
